/* Foto do hero embutida em base64.
   Motivo: o canvas do efeito de "digitalizacao" le os pixels da imagem (getImageData).
   Um arquivo .jpg comum contamina o canvas quando o site e aberto via file://,
   e o efeito quebra. Data URI nao contamina e funciona em qualquer contexto.
   Para trocar a foto: gere o base64 da nova imagem e substitua a string abaixo. */
window.HERO_IMAGE_SRC = "data:image/jpeg;base64,";
